import { existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';

/** Load the backend repo's .env (generated by `mc configure`) for local runs; real env vars always win. */
export function loadServiceEnv() {
  let dir = resolve(process.cwd());
  for (let i = 0; i < 4; i++) {
    const f = join(dir, '.env');
    if (existsSync(f) && existsSync(join(dir, 'pnpm-workspace.yaml'))) {
      const before = { ...process.env };
      process.loadEnvFile(f);
      Object.assign(process.env, before);
      return f;
    }
    dir = dirname(dir);
  }
  return undefined;
}

export function requireEnv(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`missing env ${name}`);
  return v;
}

export const isDev = () => process.env.MC_DEV === 'true';
